            module,
            modules,
            facts,
            &mut byte_helper::Proofs::new(modules, facts),
            static_schema,
            false
        )
        .unwrap(),
        "semaprax.graph.v77"
    );
    assert_eq!(build.source_graph_schemas().unwrap_err(), REPORT.legacy());
